# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZEKÂT VE SADAKANIN BİREYSEL FAYDALARI (8.2.3)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ahlaki ve Manevi Kazanımlar</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Cimrilik ve bencillik duygusunu yok eder</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Paylaşma, merhamet ve şefkati geliştirir</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Allah\'ın (cc) verdiği nimetlere şükürdür</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• İnsana iç huzuru ve manevi mutluluk verir</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Mal tutkusu ve dünya hırsından arındırır</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">Tevbe Suresi 103: Malı temizler ve arındırır</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Malın Bereketlenmesi ve Mükâfat</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Zekât kelime anlamıyla: Artma ve Bereket</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Bakara 261: 1 tohum ➔ 7 başak ➔ 700 dane</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Sebe 39: Harcanan malın yerini Allah doldurur</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Hadis: Sadaka malı eksiltmez, bereketlendirir</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Günahlara kefaret olur ve kötülükleri savar</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#166534">Veren el, alan elden üstündür (Hadis-i Şerif)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZEKÂT VE SADAKANIN TOPLUMSAL ÖNEMİ: SOSYAL ADALET</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Toplumsal Dayanışma ve Kardeşlik</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Zengin ile fakir arasında sevgi köprüsü kurar</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Kıskançlık, kin ve haset duygularını önler</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Toplumsal barış, güven ve huzuru güçlendirir</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Kimsesiz ve muhtaçların yalnızlığını giderir</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Sadaka-i cariye ile kalıcı kurumlar oluşur</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#713f12">Vakıf, aşevi, şifahane ve Sadaka Taşı geleneği</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Ekonomik Denge ve Sosyal Adalet</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Gelir dağılımındaki uçurumu azaltır</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Servetin belli ellerde toplanmasını önler (Haşr 7)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Yoksulluk kaynaklı suç oranlarını düşürür</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Paranın ekonomik dolaşıma girmesini sağlar</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Alım gücünü artırarak üretimi canlandırır</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#475569">İnfak kültürü sosyal devlet anlayışını destekler</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİR PEYGAMBER TANIYORUM: HZ. ŞUAYB (AS) VE MEDYEN HALKI (8.2.4)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Medyen ve Eyke Halkının Bozuklukları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Ticaret yolları üzerinde zengin bir kavimdi</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Tevhid inancını terk edip putlara taptılar</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Ölçü ve tartıda hile yaparak kul hakkı yediler</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Kervanların yolunu kesip güvenliği bozdular</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• İnsanların mallarını değerinden düşük aldılar</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#881337">Yeryüzünde bozgunculuk (fesat) çıkardılar</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Hz. Şuayb\'ın (as) Tebliği ve Ticaret Ahlakı</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Hitabeti güçlü: Hatîbü\'l-Enbiyâ (Peygamberlerin Hatibi)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Çağrı 1: Yalnızca Allah\'a (cc) kulluk edin (Tevhid)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Çağrı 2: Ölçüyü ve tartıyı tam ve adaletli yapın</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Çağrı 3: İnsanların eşyasını eksik vermeyin (Hûd 85)</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• Hz. Musa\'ya (as) Medyen\'de kayınpederlik yaptı</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#0f172a">İnkârcılar korkunç ses ve sarsıntıyla helak oldu</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
